import{_ as i,o as e,c as s,a0 as t}from"./chunks/framework.tsJrOMu2.js";const k=JSON.parse('{"title":"故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/troubleshooting.md","filePath":"zh/guides/troubleshooting.md"}'),n={name:"zh/guides/troubleshooting.md"};function o(l,a,d,r,h,p){return e(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h1><p>本页汇总常见问题及对应处理方式。</p><h2 id="llm-provider-问题" tabindex="-1">LLM Provider 问题 <a class="header-anchor" href="#llm-provider-问题" aria-label="Permalink to &quot;LLM Provider 问题&quot;">​</a></h2><h3 id="provider-not-found-或-providernotfounderror" tabindex="-1"><code>Provider not found</code> 或 <code>ProviderNotFoundError</code> <a class="header-anchor" href="#provider-not-found-或-providernotfounderror" aria-label="Permalink to &quot;`Provider not found` 或 `ProviderNotFoundError`&quot;">​</a></h3><p>通常是因为没有注册内建 Provider。需要在任意 agent 代码运行前增加：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@agentrail/core/providers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>这会注册 Anthropic 和 OpenAI 两个内建 Provider。</p><h3 id="_401-unauthorized-或-invalid-api-key" tabindex="-1"><code>401 Unauthorized</code> 或 <code>Invalid API Key</code> <a class="header-anchor" href="#_401-unauthorized-或-invalid-api-key" aria-label="Permalink to &quot;`401 Unauthorized` 或 `Invalid API Key`&quot;">​</a></h3><ul><li>检查环境变量是否正确设置，例如 <code>ANTHROPIC_API_KEY</code> 或 <code>OPENAI_API_KEY</code></li><li>检查密钥是否已过期或被吊销</li><li>如果使用自定义 <code>baseUrl</code>，确认对应端点接受当前密钥格式</li></ul><p>更多兼容 Provider 的配置方式，可参考 <a href="./use-openai-compatible-providers">使用 OpenAI 兼容 Provider</a>。</p><h3 id="模型或-provider-配置错误" tabindex="-1">模型或 Provider 配置错误 <a class="header-anchor" href="#模型或-provider-配置错误" aria-label="Permalink to &quot;模型或 Provider 配置错误&quot;">​</a></h3><p><code>model.provider</code> 必须与已注册的 Provider 名完全一致：</p><ul><li><code>&quot;anthropic&quot;</code>：Claude 模型</li><li><code>&quot;openai&quot;</code>：GPT 模型及兼容 API</li></ul><p>应优先排查拼写错误。报错信息通常会列出当前可用的 Provider。</p><h2 id="sandbox-问题" tabindex="-1">Sandbox 问题 <a class="header-anchor" href="#sandbox-问题" aria-label="Permalink to &quot;Sandbox 问题&quot;">​</a></h2><h3 id="cannot-connect-to-docker-daemon" tabindex="-1"><code>Cannot connect to Docker daemon</code> <a class="header-anchor" href="#cannot-connect-to-docker-daemon" aria-label="Permalink to &quot;`Cannot connect to Docker daemon`&quot;">​</a></h3><p>Sandbox 依赖可运行的 Docker daemon。先确认：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span></code></pre></div><p>如果 Docker 未启动，需要先启动再运行服务。</p><h3 id="image-not-found-或首次启动很慢" tabindex="-1"><code>Image not found</code> 或首次启动很慢 <a class="header-anchor" href="#image-not-found-或首次启动很慢" aria-label="Permalink to &quot;`Image not found` 或首次启动很慢&quot;">​</a></h3><p>Sandbox 镜像需要先拉取或在本地构建：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 拉取已发布镜像</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/yai-dev/agentrail-sandbox:latest</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或本地构建</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agentrail-sandbox:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker/sandbox</span></span></code></pre></div><p>随后确认配置中的 <code>sandbox.image</code> 与实际镜像名一致。</p><h3 id="sandbox-容器立即退出" tabindex="-1">Sandbox 容器立即退出 <a class="header-anchor" href="#sandbox-容器立即退出" aria-label="Permalink to &quot;Sandbox 容器立即退出&quot;">​</a></h3><p>先查看容器日志：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">container-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>常见原因包括：</p><ul><li>端口冲突</li><li>容器内部缺少环境变量</li><li>Docker 可用内存不足</li></ul><h2 id="session-与存储问题" tabindex="-1">Session 与存储问题 <a class="header-anchor" href="#session-与存储问题" aria-label="Permalink to &quot;Session 与存储问题&quot;">​</a></h2><h3 id="session-损坏-启动时报-parse-error" tabindex="-1">Session 损坏，启动时报 parse error <a class="header-anchor" href="#session-损坏-启动时报-parse-error" aria-label="Permalink to &quot;Session 损坏，启动时报 parse error&quot;">​</a></h3><p>如果 <code>session.jsonl</code> 或 <code>messages.jsonl</code> 在异常退出后损坏，一般有两种处理方式：</p><ol><li>删除该 session</li><li>手动修复 JSONL 文件</li></ol><p>删除方式是移除 <code>&lt;dataDir&gt;/tenants/&lt;tenantId&gt;/sessions/&lt;sessionId&gt;/</code> 对应目录。手动修复时，通常只需要打开 JSONL 文件，找到最后一条不完整记录并删除。</p><h3 id="unable-to-find-config-agentrail-yaml" tabindex="-1"><code>Unable to find config/agentrail.yaml</code> <a class="header-anchor" href="#unable-to-find-config-agentrail-yaml" aria-label="Permalink to &quot;`Unable to find config/agentrail.yaml`&quot;">​</a></h3><p>配置加载器会从当前工作目录向上查找。应确认：</p><ul><li>服务是在项目根目录启动</li><li>或已通过 <code>AGENTRAIL_CONFIG_PATH</code> 指定绝对路径</li></ul><h2 id="编排问题" tabindex="-1">编排问题 <a class="header-anchor" href="#编排问题" aria-label="Permalink to &quot;编排问题&quot;">​</a></h2><h3 id="子-agent-一直没有响应" tabindex="-1">子 agent 一直没有响应 <a class="header-anchor" href="#子-agent-一直没有响应" aria-label="Permalink to &quot;子 agent 一直没有响应&quot;">​</a></h3><p>先检查 <code>agentrail.yaml</code> 中的以下配置：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">orchestration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  subagent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    pollIntervalMs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 越小轮询越快，但 CPU 更高</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    fakeExecution</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 为空时才会真实执行</span></span></code></pre></div><p>如果 <code>fakeExecution</code> 被设置为 <code>&quot;echo&quot;</code>，子 agent 不会调用 LLM，只会原样回显输入。</p><h3 id="改完代码后-旧的编排状态仍然被回放" tabindex="-1">改完代码后，旧的编排状态仍然被回放 <a class="header-anchor" href="#改完代码后-旧的编排状态仍然被回放" aria-label="Permalink to &quot;改完代码后，旧的编排状态仍然被回放&quot;">​</a></h3><p>如果编排逻辑已经变化，但管理器在启动时仍然回放旧事件，开发期最直接的处理方式是删除对应 session 目录，重新开始一轮干净会话。</p><h3 id="wait-条件一直不满足" tabindex="-1">Wait 条件一直不满足 <a class="header-anchor" href="#wait-条件一直不满足" aria-label="Permalink to &quot;Wait 条件一直不满足&quot;">​</a></h3><ul><li>检查目标 <code>agentIds</code> 是否正确</li><li>检查 <code>kind</code> 是否匹配：等待任务完成通常用 <code>&quot;agent-idle&quot;</code>，等待终止通常用 <code>&quot;agent-closed&quot;</code></li><li>如果使用 <code>match: &quot;all&quot;</code>，则所有列出的 agent 都必须满足条件</li><li>如果配置了 <code>timeoutAt</code>，超时后会以 <code>timed_out</code> 状态返回</li></ul><h2 id="构建与开发问题" tabindex="-1">构建与开发问题 <a class="header-anchor" href="#构建与开发问题" aria-label="Permalink to &quot;构建与开发问题&quot;">​</a></h2><h3 id="拉取最新代码后出现-typescript-错误" tabindex="-1">拉取最新代码后出现 TypeScript 错误 <a class="header-anchor" href="#拉取最新代码后出现-typescript-错误" aria-label="Permalink to &quot;拉取最新代码后出现 TypeScript 错误&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:packages</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>仓库使用 project references。多数类型解析问题可以通过完整重建解决。</p><h3 id="测试时报-module-not-found" tabindex="-1">测试时报 <code>module not found</code> <a class="header-anchor" href="#测试时报-module-not-found" aria-label="Permalink to &quot;测试时报 `module not found`&quot;">​</a></h3><p>通常是因为运行测试前没有先构建包：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:packages</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><h2 id="仍未解决" tabindex="-1">仍未解决 <a class="header-anchor" href="#仍未解决" aria-label="Permalink to &quot;仍未解决&quot;">​</a></h2><p>如果以上方法仍无帮助，可继续：</p><ol><li>搜索 <a href="https://github.com/yai-dev/agentrail/issues" target="_blank" rel="noreferrer">existing issues</a></li><li>提交 <a href="https://github.com/yai-dev/agentrail/issues/new?template=bug_report.md" target="_blank" rel="noreferrer">bug report</a>，并附上复现步骤</li></ol>',55)])])}const u=i(n,[["render",o]]);export{k as __pageData,u as default};
